mapper.select:
SELECT L.COMPANY_CODE, L.USER_ID, U.USER_NAME, U.DEPT_NAME, U.POSITION, L.STATUS FROM TB_LOGIN_MASTER L JOIN TB_USER_MASTER U ON L.COMPANY_CODE = U.COMPANY_CODE AND L.USER_ID = U.USER_ID WHERE L.COMPANY_CODE = #{companyCode}
AND U.USER_NAME LIKE '%' || #{userName} || '%'
AND U.DEPT_CODE = #{deptCode}
AND U.POSITION = #{positionCode}
ORDER BY U.USER_NAME

mapper.delete:
DELETE FROM TB_USER_MENU_AUTH
WHERE COMPANY_CODE = #{companyCode}
  AND USER_ID = #{userId}
